# Transform complex nested API responses
api_data = {
    'users': [
        {'id': 1, 'name': 'Alice', 'orders': [
            {'oid': 'O1', 'items': ['laptop', 'mouse'], 'total': 1029},
            {'oid': 'O2', 'items': ['book'], 'total': 40},
        ]},
        {'id': 2, 'name': 'Bob', 'orders': [
            {'oid': 'O3', 'items': ['keyboard'], 'total': 79},
        ]},
    ]
}

# Flatten: all (user_name, order_id, item) combinations
flat = [
    (user['name'], order['oid'], item)
    for user in api_data['users']
    for order in user['orders']
    for item in order['items']
]
print(flat)
# [('Alice','O1','laptop'), ('Alice','O1','mouse'),
#  ('Alice','O2','book'), ('Bob','O3','keyboard')]

# User total spending
user_spend = {
    user['name']: sum(order['total'] for order in user['orders'])
    for user in api_data['users']
}
print(user_spend)  # {'Alice': 1069, 'Bob': 79}
```
